import glob,re,os
items={}
for f in glob.glob('/home/axel/LeanAlgebraicGeometry-Horizon/.archon-horizon/roadmap/items/*.yaml'):
    t=open(f).read()
    i=re.search(r'^id:\s*(\S+)',t,re.M).group(1)
    st=re.search(r'^status:\s*(\S+)',t,re.M)
    pa=re.search(r'^\s*parent:\s*(\S+)',t,re.M)
    items[i]=(st.group(1) if st else '?', pa.group(1) if pa else None)
for k in ('AJC.rr','AJC.rr.extuniform','AJC.picrep','AJC.picrep.tensor','AJC.jacobian.assembly','AJC.jacobian.assembly.reachability','AJC.jacobian'):
    print(f"  {k:42} {items.get(k,('MISSING',None))}")
print()
# recompute all parent/child mismatches
kids={}
for i,(st,pa) in items.items():
    if pa: kids.setdefault(pa,[]).append((i,st))
print("=== mismatches: done parent with open child ===")
for p,ks in sorted(kids.items()):
    pst=items.get(p,('?',None))[0]
    openk=[k for k,s in ks if s not in ('done','cancelled','dropped')]
    if pst=='done' and openk: print(f"  {p} (done) <- open {openk}")
print("=== mismatches: all children done, parent open ===")
for p,ks in sorted(kids.items()):
    pst=items.get(p,('?',None))[0]
    if pst not in ('done','cancelled','dropped') and ks and all(s=='done' for k,s in ks):
        print(f"  {p} ({pst}) <- all {len(ks)} children done")
